import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Proving guards, not guessing them","description":"Guard validation used to be textual, a call with the right name near the sink. The value lattice changed that.","frontmatter":{"title":"Proving guards, not guessing them","date":"2026-09-21T00:00:00.000Z","description":"Guard validation used to be textual, a call with the right name near the sink. The value lattice changed that."},"headers":[],"relativePath":"blog/2026-09-21-value-aware-guards.md","filePath":"blog/2026-09-21-value-aware-guards.md"}'),r={name:"blog/2026-09-21-value-aware-guards.md"};function i(s,e,d,l,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="proving-guards-not-guessing-them" tabindex="-1">Proving guards, not guessing them <a class="header-anchor" href="#proving-guards-not-guessing-them" aria-label="Permalink to &quot;Proving guards, not guessing them&quot;">​</a></h1><p>Early versions of the engine accepted a guard if a plausible-sounding check appeared on the path to a sink. That works until it doesn&#39;t: <code>if (i &lt; 10)</code> guards <code>arr[i]</code>, but only because <code>10</code> happens to relate to the array, knowledge the text of the call does not carry.</p><p>The value lattice fixes the reasoning, not the pattern:</p><ul><li><strong>Constants and ranges</strong> flow through the analysis.</li><li><strong>Branch sharpening</strong> narrows values inside each <code>if</code>/<code>match</code> arm by the constraints the predicate implies.</li><li><strong>The GuardMap</strong> records which guard dominates which block, and <code>if i &lt; arr.len()</code> <em>provably</em> dominates <code>arr[i]</code> inside the arm.</li></ul><p>The same machinery powers the learned policy checks: a corpus bundle can require that a call only happen behind a range check, and the engine accepts a guard only when the lattice proves the bound, false positives on clean code drop accordingly.</p><p>This is the foundation the out-of-bounds checker is built on, and the relational (octagon) domain is the next step: tracking <em>relationships</em> between variables, not just their individual ranges.</p>',6)])])}const p=a(r,[["render",i]]);export{g as __pageData,p as default};
